CREATE OR REPLACE FUNCTION public.check_job_unit_pairing_company(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_operation = 'DELETE' OR (p_operation = 'UPDATE'
    AND (p_new->>'companyId', p_new->>'jobId', p_new->>'jobMaterialId', p_new->>'sourceId', p_new->>'outputId')
      IS NOT DISTINCT FROM
        (p_old->>'companyId', p_old->>'jobId', p_old->>'jobMaterialId', p_old->>'sourceId', p_old->>'outputId')) THEN
    RETURN;
  END IF;

  -- The older parents have globally unique, single-column keys. Validate
  -- their company and the job material's parent without adding indexes to
  -- every existing tracked unit merely to express composite foreign keys.
  IF NOT EXISTS (
    SELECT 1 FROM job j
    JOIN "trackedEntity" source ON source.id = p_new->>'sourceId' AND source."companyId" = j."companyId"
    JOIN "trackedEntity" output ON output.id = p_new->>'outputId' AND output."companyId" = j."companyId"
    WHERE j.id = p_new->>'jobId' AND j."companyId" = p_new->>'companyId'
      AND (p_new->>'jobMaterialId' IS NULL OR EXISTS (
        SELECT 1 FROM "jobMaterial" m WHERE m.id = p_new->>'jobMaterialId'
          AND m."companyId" = j."companyId" AND m."jobId" = j.id
      ))
  ) THEN
    RAISE EXCEPTION 'The paired units and job material must belong to this job and company.';
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_job_unit_pairing_serial(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company text := p_new->>'companyId';
  v_item text := COALESCE(p_new->>'itemId', CASE WHEN p_new->>'sourceDocument' = 'Item' THEN p_new->>'sourceDocumentId' END);
  v_serial text := p_new->>'readableId';
BEGIN
  IF p_operation = 'DELETE' OR (p_operation = 'UPDATE'
    AND (p_new->>'readableId', p_new->>'companyId', p_new->>'itemId', p_new->>'sourceDocument', p_new->>'sourceDocumentId')
      IS NOT DISTINCT FROM
        (p_old->>'readableId', p_old->>'companyId', p_old->>'itemId', p_old->>'sourceDocument', p_old->>'sourceDocumentId')) THEN
    RETURN;
  END IF;

  -- The foreign keys retain immutable identity on delete. On an update,
  -- prevent an edit from making the two ends disagree with their snapshot.
  IF p_operation = 'UPDATE' AND EXISTS (
    SELECT 1 FROM "jobUnitPairing" p
    WHERE p."companyId" = p_old->>'companyId' AND p."releasedAt" IS NULL
      AND (p."sourceId" = p_old->>'id' OR p."outputId" = p_old->>'id')
  ) THEN
    RAISE EXCEPTION 'This unit is paired to a packing job. Correct the issue before changing the serial or item.';
  END IF;

  IF v_item IS NULL OR NULLIF(btrim(v_serial), '') IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM "companySettings" cs WHERE cs.id = v_company AND cs."serialNumberFromComponent")
    AND NOT EXISTS (SELECT 1 FROM "jobUnitPairing" p WHERE p."companyId" = v_company) THEN
    RETURN;
  END IF;

  -- The issue posting takes the same lock before checking existing serials.
  -- This keeps a manual or generated number on the same sales SKU from
  -- racing an issue that is about to bind that number.
  PERFORM pg_advisory_xact_lock(hashtextextended(jsonb_build_array(v_company, v_item, v_serial)::text, 0));
  IF EXISTS (
    SELECT 1 FROM "trackedEntity" output
    JOIN "jobUnitPairing" p ON p."companyId" = output."companyId" AND p."outputId" = output.id
    WHERE output."companyId" = v_company AND output."readableId" = v_serial
      AND output."itemId" = v_item AND output.id <> p_new->>'id' AND p."releasedAt" IS NULL
  ) THEN
    RAISE EXCEPTION 'This sales item already has a packed unit with serial %.', v_serial;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_finish_job_operation(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job_location_id TEXT;
  v_job_storage_unit_id TEXT;
  v_job_quantity NUMERIC;
  v_sales_order_id TEXT;
  v_quantity_complete NUMERIC;
  v_quantity_lost NUMERIC;
  v_quantity_received NUMERIC;
  v_job_status TEXT;
  v_paired BOOLEAN;
BEGIN
  IF p_operation != 'UPDATE' THEN RETURN; END IF;
  IF (p_new->>'status') != 'Done' OR (p_old->>'status') = 'Done' THEN RETURN; END IF;

  UPDATE "productionEvent"
  SET "endTime" = NOW()
  WHERE "jobOperationId" = p_new->>'id'
    AND "endTime" IS NULL;

  UPDATE "jobOperation" op
  SET status = 'Ready'
  WHERE EXISTS (
    SELECT 1
    FROM "jobOperationDependency" dep
    WHERE dep."operationId" = op.id
      AND dep."dependsOnId" = p_new->>'id'
      AND op.status = 'Waiting'
  )
  AND NOT EXISTS (
    SELECT 1
    FROM "jobOperationDependency" dep2
    JOIN "jobOperation" jo2 ON jo2.id = dep2."dependsOnId"
    WHERE dep2."operationId" = op.id
      AND jo2.status != 'Done'
      AND jo2.id != p_new->>'id'
  );

  v_paired := job_requires_serial_pairing(p_new->>'jobId', p_new->>'companyId');
  IF v_paired THEN
    -- Serialize terminal Finish with a concurrent partial ERP receipt.
    SELECT status INTO v_job_status FROM "job"
    WHERE id = p_new->>'jobId' AND "companyId" = p_new->>'companyId' FOR UPDATE;
  ELSE
    SELECT status INTO v_job_status FROM "job" WHERE id = p_new->>'jobId';
  END IF;
  -- A Draft/Planned job's operation can only reach Done through a released
  -- BATCH (batch release outranks job release for floor visibility), so the
  -- run genuinely happened. Completing the batch must complete those jobs
  -- too: otherwise their output lots exist while their receipts never post,
  -- and a merged output lot carries only the received fraction of its
  -- quantity.
  IF v_job_status NOT IN ('Ready', 'In Progress', 'Paused')
     AND NOT (
       (p_new->>'jobOperationBatchId') IS NOT NULL
       AND v_job_status IN ('Draft', 'Planned')
     ) THEN
    RETURN;
  END IF;

  IF is_last_job_operation(p_new->>'id') THEN
    SELECT "locationId", "storageUnitId", quantity, "salesOrderId", "quantityReceivedToInventory"
    INTO v_job_location_id, v_job_storage_unit_id, v_job_quantity, v_sales_order_id, v_quantity_received
    FROM "job"
    WHERE id = p_new->>'jobId';

    -- The units out of the routing's final operations. Two kinds of final
    -- operation report differently:
    --   * the routing's own (parallel "With Previous" operations at the end)
    --     each see EVERY unit, so a unit is finished once it has come through
    --     all of them: the smallest count. Summing them completed a 3-unit job
    --     at 6, which a serial job then refused for want of units. One closed
    --     with Finish and no quantity reports nothing, so it is left out.
    --   * a rework branch triggered at the final operation (trigger-rework)
    --     carries only the reworked units, which the operation it came from
    --     reports as reworked, not complete: those add on top.
    -- This runs BEFORE the update is written, so the table still holds the
    -- finishing operation's old row: its quantity comes from p_new. An outside
    -- processing receipt sets Done and quantityComplete in one update.
    v_quantity_complete := (
      SELECT COALESCE(MIN(terminal_jo."quantityComplete") FILTER (
               WHERE terminal_jo."reworkId" IS NULL AND terminal_jo."quantityComplete" > 0
             ), 0)
           + COALESCE(SUM(terminal_jo."quantityComplete") FILTER (
               WHERE terminal_jo."reworkId" IS NOT NULL
             ), 0)
      FROM (
        SELECT jo.id, jo."jobId", jo."jobMakeMethodId", jo."reworkId", jo.status,
               CASE WHEN jo.id = p_new->>'id'
                 THEN COALESCE((p_new->>'quantityComplete')::NUMERIC, 0)
                 ELSE jo."quantityComplete"
               END AS "quantityComplete"
        FROM "jobOperation" jo
        WHERE jo."jobId" = p_new->>'jobId'
      ) terminal_jo
      INNER JOIN "jobMakeMethod" terminal_jmm ON terminal_jmm.id = terminal_jo."jobMakeMethodId"
      WHERE terminal_jo."jobId" = p_new->>'jobId'
        AND terminal_jmm."parentMaterialId" IS NULL
        AND terminal_jo.status <> 'Canceled'
        AND NOT EXISTS (
          SELECT 1
          FROM "jobOperationDependency" dep
          INNER JOIN "jobOperation" child_jo ON child_jo.id = dep."operationId"
          INNER JOIN "jobMakeMethod" child_jmm ON child_jmm.id = child_jo."jobMakeMethodId"
          WHERE dep."dependsOnId" = terminal_jo.id
            AND child_jmm."parentMaterialId" IS NULL
        )
    );

    -- An ordinary quantity-less Finish can receive the whole planned job.
    -- A pack-out must account for each piece first, even when the Finish
    -- button is used instead of the ERP receipt. Rework is still live WIP.
    IF v_paired THEN
      v_quantity_complete := GREATEST(COALESCE(v_quantity_complete, 0), COALESCE(v_quantity_received, 0));
      IF v_quantity_complete + job_scrapped_paired_output_count(p_new->>'jobId', p_new->>'companyId') < v_job_quantity THEN
        RAISE EXCEPTION 'Finish requires every planned pack-out unit to be logged or scrapped. Receive completed units from the job to leave the remaining work open.';
      END IF;
    END IF;

    IF COALESCE(v_quantity_complete, 0) = 0 THEN
      -- The zero fallback exists for the quantity-less Finish flow (no
      -- productionQuantity ever recorded). When the job DID record scrap or
      -- rework, zero completions is a real outcome (e.g. a fully-scrapped
      -- lot) — falling back would receive scrapped units into stock.
      SELECT COALESCE(SUM(COALESCE("quantityScrapped", 0) + COALESCE("quantityReworked", 0)), 0)
      INTO v_quantity_lost
      FROM "jobOperation"
      WHERE "jobId" = p_new->>'jobId';

      IF v_quantity_lost = 0 THEN
        v_quantity_complete := v_job_quantity;
      ELSE
        -- Nothing to receive: close the job without posting Assembly Output.
        -- Materials were already consumed by the scrap/complete flows; WIP
        -- cost disposition for fully-scrapped jobs is a costing follow-up.
        UPDATE "job"
        SET status = 'Completed',
            "completedDate" = NOW(),
            "quantityComplete" = 0,
            "updatedBy" = COALESCE(p_new->>'updatedBy', p_new->>'createdBy'),
            "updatedAt" = NOW()
        WHERE id = p_new->>'jobId';
        RETURN;
      END IF;
    END IF;

    -- A reopened job may already have received more than its operations now
    -- report. complete_job_to_inventory refuses a quantity below what was
    -- received, and refusing here would block the Done update itself.
    v_quantity_complete := GREATEST(v_quantity_complete, COALESCE(v_quantity_received, 0));

    PERFORM util.post_job_receipt(
      p_job_id := p_new->>'jobId',
      p_quantity_complete := v_quantity_complete,
      p_storage_unit_id := v_job_storage_unit_id,
      p_location_id := v_job_location_id,
      p_company_id := p_new->>'companyId',
      p_user_id := COALESCE(p_new->>'updatedBy', p_new->>'createdBy'),
      p_expected_serials := NULL,
      p_automatic_finish := true
    );
  END IF;
END;
$function$;

-- jobUnitPairing
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'jobUnitPairing' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, 'jobUnitPairing');
  END LOOP;
END
$authz$;
ALTER TABLE public."jobUnitPairing" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "SELECT" ON "public"."jobUnitPairing" FOR SELECT USING ("companyId" = ANY ((SELECT get_companies_with_employee_role())::text[]));

-- event triggers (packages/database/src/event-system/attachments.ts)
SET lock_timeout = '5s';
SELECT set_event_triggers('jobUnitPairing', ARRAY['check_job_unit_pairing_company']::text[], ARRAY[]::text[], false, ARRAY[]::text[]);
SELECT set_event_triggers('trackedEntity', ARRAY['check_tracked_entity_inspection_hold', 'check_job_unit_pairing_serial']::text[], ARRAY[]::text[], false, ARRAY['broadcast_table_changes']::text[]);
RESET lock_timeout;
